  const TASKS_BY_GROUP = TASKS.reduce((acc, t, i) => { (acc[t.g] = acc[t.g] || []).push(i); return acc; }, {});

  // Quantity rules — how many units of a deliverable the scope drivers imply.
  const QTY_RULES = {
    one: () => 1,
    two: () => 2,
    months: (d) => Math.max(1, d.months),
    months_double: (d) => Math.max(2, d.months * 2),
    months_third: (d) => Math.max(2, Math.round(d.months / 3)),
    weeks: (d) => Math.max(4, Math.round(d.months * 4.33)),
    waves: (d) => Math.max(1, d.waves),
    waves_double: (d) => Math.max(2, d.waves * 2),
    units: (d) => Math.max(1, d.units),
    units_min2: (d) => Math.max(2, d.units),
    geos: (d) => Math.max(1, d.geos),
    modules: (d) => Math.max(1, d.modules),
    modules_half: (d) => Math.max(2, Math.round(d.modules / 2)),
    modules_third: (d) => Math.max(1, Math.round(d.modules / 3)),
    extra_languages: (d) => Math.max(0, d.modules * Math.max(0, d.languages - 1)),
    comms_cadence: (d) => Math.max(6, d.months * 2),
    hypercare_double: (d) => Math.max(2, d.hypercareMonths * 2),
    // Session counts take the mode's capacity factor: a physical class seats
    // fewer people than the same class run virtually, so it takes more runs.
    trainer_sessions: (d, cap) => Math.max(1, Math.ceil(Math.ceil(d.headcount / 50) / Math.max(1, 12 * cap))),
    training_sessions: (d, cap) => Math.max(1, Math.ceil(d.headcount / Math.max(1, (d.sessionSize || 20) * cap)))
  };

  const CAT_BY_ID = Object.fromEntries(CATALOG.map((c) => [c.id, c]));

  /* ---- Hours library: task hours resolve through the archetype matrix ---- */

  const LEVELS = ["Simple", "Standard", "Complex"];

  function archetypeHours(archetype, complexity) {
    const ov = (state.archetypes || {})[archetype] || {};
    if (ov[complexity] > 0) return +ov[complexity];
    const row = ARCHETYPE_HOURS[archetype] || {};
    return row[complexity] > 0 ? row[complexity] : null;
  }

  // Some archetypes are not defined at every level — "Recurring PMO / Admin" has
  // no Complex, and an admin can blank any cell. Step toward Standard until the
  // matrix has something to say rather than dropping the task's hours to zero.
  function archetypeHoursClamped(archetype, level) {
    const order = level === "Complex" ? ["Complex", "Standard", "Simple"]
      : level === "Simple" ? ["Simple", "Standard", "Complex"]
      : ["Standard", "Complex", "Simple"];
    for (const l of order) {
      const h = archetypeHours(archetype, l);
      if (h != null) return { hours: h, level: l };
    }
    return null;
  }

  // level === null means "leave each task at its own graded complexity".
  function taskHoursAt(i, level) {
    const t = TASKS[i];
    const ov = (state.taskHours || {})[i];
    if (ov > 0) return +ov;                       // an admin pin is a pin
    const hit = archetypeHoursClamped(t.a, level || t.c);
    return hit ? hit.hours : t.h;
  }

  function taskHours(i) { return taskHoursAt(i, null); }

  function taskEnabled(i) { return !(state.taskOff || {})[i]; }

  function libraryHours(groupId, level) {
    const idx = TASKS_BY_GROUP[groupId] || [];
    let hours = 0, n = 0;
    idx.forEach((i) => { if (taskEnabled(i)) { hours += taskHoursAt(i, level || null); n++; } });
    return { hours, n, total: idx.length };
  }

  function libraryTaskNames(groupId) {
    return (TASKS_BY_GROUP[groupId] || []).filter(taskEnabled).map((i) => TASKS[i].t);
  }

  // A deliverable's natural grade: the level its own tasks are mostly written at,
  // weighted by hours so a single trivial checklist item cannot outvote the
  // substantive work. Deliverables built mostly from Complex tasks default to
  // Complex rather than being flattened to Standard.
  function baselineLevel(groupId) {
    const weight = { Simple: 0, Standard: 0, Complex: 0 };
    (TASKS_BY_GROUP[groupId] || []).forEach((i) => {
      if (!taskEnabled(i)) return;
      const t = TASKS[i];
      if (weight[t.c] === undefined) return;
      weight[t.c] += taskHoursAt(i, null);
    });
    let best = "Standard", top = -1;
    LEVELS.forEach((l) => { if (weight[l] > top) { top = weight[l]; best = l; } });
    return top > 0 ? best : "Standard";
  }

  // The typical size of a catalogue deliverable, in tasks. Used to scale a
  // free-text line, where there is no task list to add up.
  function medianTaskCount() {
    const counts = CATALOG.map((c) => libraryHours(c.id).n).filter((n) => n > 0).sort((a, b) => a - b);
    if (!counts.length) return 4;
    const m = Math.floor(counts.length / 2);
    return counts.length % 2 ? counts[m] : Math.round((counts[m - 1] + counts[m]) / 2);
  }

  /* =====================================================================
     Mode of conduct — a physical workshop is a different job from a virtual
     one. It costs more effort (travel, venue, printed materials, setup) and
     it seats fewer people, so a physical rollout also needs more sessions.
     ===================================================================== */

  const MODES = [
    { id: "virtual", name: "Virtual", short: "Virtual" },
    { id: "blended", name: "Blended", short: "Blended" },
    { id: "physical", name: "Physical", short: "Physical" }
  ];

  const MODE_FACTORS = {
    virtual:  { effort: 0.85, capacity: 1.00 },
    blended:  { effort: 1.00, capacity: 0.85 },
    physical: { effort: 1.15, capacity: 0.75 }
  };

  /* =====================================================================
     Globalisation and localisation

     A global rollout builds the change material once, centrally, then adapts
     it market by market. The two streams carry different quantities and
     different effort, so they are estimated separately and shown separately.
     ===================================================================== */

  const STREAMS = [
    { id: "global", name: "Global", verb: "Globalisation",
      blurb: "Built once, centrally — the master set of change deliverables." },
    { id: "local", name: "Local", verb: "Localisation",
      blurb: "The global set adapted per market — translation, local process, local delivery." }
  ];

  // Adapting a deliverable for a market costs a fraction of building it.
  const LOCALISATION_FACTOR = 0.35;

  // One review cycle is a round with the client plus a round of our own QA,
  // each expressed as a share of the build effort it reviews.
  const REVIEW_CLIENT_PCT = 2.5;
  const REVIEW_OURS_PCT = 25;

  const activeStreams = () =>
    STREAMS.filter((st) => state.scopeType === "both" || state.scopeType === st.id);

  const streamActive = (id) => state.scopeType === "both" || state.scopeType === id;

  function localisationFactor() {
    const v = state.localisationFactor;
    return v > 0 ? v / 100 : LOCALISATION_FACTOR;
  }

  function reviewPct(who) {
    const ov = (state.reviewPct || {})[who];
    if (ov >= 0 && ov !== "" && ov !== null) return +ov / 100;
    return (who === "client" ? REVIEW_CLIENT_PCT : REVIEW_OURS_PCT) / 100;
  }

  const reviewCycles = () => Math.min(3, Math.max(1, +state.reviewCycles || 1));

  // Deloitte's share of a stream; the client carries the rest.
  function ourShare(streamId) {
    const v = (state.involvement || {})[streamId];
    const pct = (v === "" || v === null || v === undefined) ? 100 : +v;
    return Math.min(100, Math.max(0, pct)) / 100;
  }

  // Deliverables where how it is conducted is a genuine choice. Everything else
  // is a document or an asset, and the control is hidden rather than defaulted.
  const MODE_APPLIES = new Set([
    "stakeholder_sessions", "change_network", "briefings", "adoption_clinics",
    "expert_groups", "peer_groups", "t3", "eu_training", "local_training",
    "uat_training", "orientation", "steerco", "working_group"
  ]);

  function modeFactor(modeId, kind) {
    const ov = (state.modeFactors || {})[modeId] || {};
    if (ov[kind] > 0) return +ov[kind];
    return (MODE_FACTORS[modeId] || MODE_FACTORS.blended)[kind];
  }

  // Lines are keyed by stream, so the same deliverable can be graded and
  // staffed differently globally and locally.
  const lineKey = (stream, catId) => stream + ":" + catId;

  function lineMode(catId, key) {
    if (!MODE_APPLIES.has(catId)) return null;
    return (state.lineMode || {})[key] || state.deliveryMode || "blended";
  }

  function lineLevel(catId, key) {
    return (state.lineComplexity || {})[key] || baselineLevel(catId);
  }

  /* =====================================================================
     Scope drivers
     ===================================================================== */

  const DRIVERS = [
    { key: "headcount", label: "Impacted people", type: "number", def: 500, step: 50,
      rx: /([\d][\d,\.]{1,9})\s*(?:\+\s*)?(?:end[\s-]?users|users|employees|staff|headcount|impacted people|people impacted|colleagues|personnel)/i },
    { key: "units", label: "Business units / functions", type: "number", def: 3, step: 1,
      rx: /(\d{1,3})\s*(?:business units|bus\b|entities|departments|functions|divisions|process areas|workstreams)/i },
    { key: "geos", label: "Countries / sites", type: "number", def: 1, step: 1,
      rx: /(\d{1,3})\s*(?:countries|geographies|regions|markets|sites|locations|plants|offices)/i },
    { key: "languages", label: "Languages", type: "number", def: 1, step: 1,
      rx: /(\d{1,2})\s*(?:languages|local languages)/i },
    { key: "waves", label: "Deployment waves", type: "number", def: 1, step: 1,
      rx: /(\d{1,2})\s*(?:waves|releases|go[\s-]?lives|deployment phases|rollout phases|tranches)/i },
    { key: "months", label: "Programme duration (months)", type: "number", def: 9, step: 1,
      rx: /(?:duration of|period of|runs? for|lasting|spanning|contract period of)\s*(?:approximately\s*)?\(?\s*(\d{1,3})\s*\)?\s*(?:calendar\s*)?months?|(\d{1,3})[\s-]*month\s*(?:programme|program|project|engagement|contract|implementation)/i },
    { key: "modules", label: "Training modules", type: "number", def: 6, step: 1,
      rx: /(\d{1,3})\s*(?:training modules|modules|courses|curricula)/i },
    { key: "sessionSize", label: "Trainees per session", type: "number", def: 20, step: 5,
      rx: /(?:participants?|trainees|pax)\s*per\s*(?:training\s*)?session[^.]{0,80}?\(?\s*(\d{1,3})\s*\)?|(?:not more than|maximum of|up to)\s*\(?\s*(\d{1,3})\s*\)?\s*(?:participants?|trainees|pax)\s*(?:per|in each)/i },
    { key: "hypercareMonths", label: "Hypercare (months)", type: "number", def: 2, step: 1,
      rx: /(?:hypercare|hyper-care|post[\s-]?go[\s-]?live support)[^.\n]{0,60}?(\d{1,2})\s*months?|(\d{1,2})\s*months?\s*(?:of\s+)?(?:hypercare|hyper-care)/i },
    { key: "complexity", label: "Complexity", type: "select", def: 3,
      options: [[1, "1 — Simple, single system"], [2, "2 — Low"], [3, "3 — Typical"], [4, "4 — High"], [5, "5 — Very high, multi-system"]] },
    { key: "maturity", label: "Client CM maturity", type: "select", def: "medium",
      options: [["low", "Low — starting from scratch"], ["medium", "Medium — some practice"], ["high", "High — mature CM function"]] }
  ];

  const DRIVER_DEF = Object.fromEntries(DRIVERS.map((d) => [d.key, d.def]));

  // A blank driver is "not stated yet", not zero. The field stays empty on
  // screen and reads as assumed, while the maths falls back to the seeded
  // default so a half-filled scope still produces a sane estimate.
  function driverValue(key) {
    const raw = state.drivers[key];
    if (raw === "" || raw === null || raw === undefined) return DRIVER_DEF[key];
    const d = DRIVERS.find((x) => x.key === key);
    if (d && d.type === "select") return raw;
    const n = parseFloat(raw);
    return isFinite(n) ? n : DRIVER_DEF[key];
  }

  function effDrivers() {
    return Object.fromEntries(DRIVERS.map((d) => [d.key, driverValue(d.key)]));
  }

  const COMPLEXITY_MULT = { 1: 0.85, 2: 0.92, 3: 1, 4: 1.15, 5: 1.35 };
  const MATURITY_MULT = { low: 1.1, medium: 1, high: 0.92 };

